+// Sites: the kitchens Larder serves. Every location belongs to one site and a
+// batch belongs to the site of its location. Items, suppliers, recipes and
+// dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and is at `site` (any site when `site` is undefined). */
+export function locationInSite(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && (site === undefined || l.site === site));
+}
+
+/** True when the batch is at `site` (always when `site` is undefined). */
+export function batchInSite(store, batch, site) {
+  return site === undefined || locationInSite(store, batch.location, site);
+}
