--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,103 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts one batch of item 4 (5 kg) into the annex fridge through an order.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 4, qty: 5 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return res.body.batches[0];
+}
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const a = (await handle({ path: "/batches" })).body;
+  const b = (await handle({ path: "/batches", headers: { "x-larder-site": "main" } })).body;
+  assert.deepEqual(a, b);
+  assert.ok(a.length > 0);
+});
+
+test("batches and stock on hand only show the request's site; items are shared", async () => {
+  const { handle } = app();
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body, []);
+  const batch = await stockAnnex(handle);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batch.id]);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batch.id));
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: `/batches/${batch.id}`, headers: ANNEX })).status, 200);
+  const annexItems = (await handle({ path: "/items", headers: ANNEX })).body;
+  const mainItems = (await handle({ path: "/items" })).body;
+  assert.equal(annexItems.length, mainItems.length);
+  assert.equal(annexItems.find((i) => i.id === 4).onHand, 5);
+  assert.equal(mainItems.find((i) => i.id === 4).onHand, 12.5);
+  assert.equal(annexItems.find((i) => i.id === 1).onHand, 0);
+});
+
+test("orders are received only into the request's site", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 4, qty: 5 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "AX-1", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking and waste use the request's site only", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+  const batch = await stockAnnex(handle);
+  assert.equal((await handle({ method: "POST", path: `/batches/${batch.id}/waste`, body: { qty: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", headers: ANNEX, body: { qty: 0.5 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/batches/${batch.id}/waste`, headers: ANNEX, body: { qty: 1 } })).status, 201);
+  assert.equal(store.data.batches.find((b) => b.id === batch.id).qty, 4);
+});
+
+test("alerts and stock value are per site", async () => {
+  const { handle } = app();
+  const mainValue = (await handle({ path: "/reports/stock-value" })).body.totalCents;
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 0);
+  await stockAnnex(handle);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 5 * 85);
+  assert.equal((await handle({ path: "/reports/stock-value" })).body.totalCents, mainValue);
+  const annex = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(annex.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(annex.lowStock.some((i) => i.name === "flour"));
+  const main = (await handle({ path: "/alerts" })).body;
+  assert.ok(!main.expiring.some((b) => b.lot === "AX-1"));
+  assert.ok(main.expiring.some((b) => b.lot === "HD-1022"));
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: 6, counted: 12 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX })).status, 404);
+  const annexTake = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(annexTake.status, 201);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await stockAnnex(handle);
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(!keys.includes("low:2026-10-28"), "main has nothing below its minimum");
+  assert.ok(keys.includes("low:2026-10-28:annex"));
+  assert.ok(store.data.outbox.some((m) => m.kind === "expiry" && m.subject.includes("AX-1")));
+});
